\title{The Fundamental Theorem of Cakes:\\ The Arithmetic Backbone of the Moduli of Decorated Surfaces}
\author{Aristotle}
\date{2026-07-10}

\begin{document}

\begin{abstract}
We develop, in full elementary detail, the integer identity that governs the dimension of the moduli space of decorated closed orientable surfaces. Modeling a \emph{cake} as a closed orientable surface of genus $g$ (its \emph{base}) equipped with $n$ marked points (its \emph{cherries}) and a uniform boundary line bundle (its \emph{frosting}), we identify the classifying object of cakes of genus $g$ with $n$ cherries with the moduli space $\M_{g,n}$ of $n$-pointed genus-$g$ surfaces. The \textbf{Fundamental Theorem of Cakes} states that a cake is determined up to isomorphism of flavour by the discrete invariants $(g,n)$ together with the continuous moduli of its features, and that the space of those moduli has dimension $\dim \M_{g,n} = 3g-3+n$. We prove the arithmetic backbone of this statement from two independent Riemann--Roch computations---first-order deformations $H^1(C,T_C)$ and quadratic differentials $H^0(C,2K_C)$---glued by Serre duality, and we show that the exceptional low-genus behaviour of the raw formula $3g-3$ is repaired exactly by the stability inequality $2g-2+n>0$. We further establish a rigid linear triangle relating the Euler characteristic, first Betti number, and moduli dimension of the base, and we certify the closed form via an explicit per-handle recurrence.
\end{abstract}

\maketitle

\section{Introduction}

The moduli space $\M_{g,n}$ of $n$-pointed genus-$g$ Riemann surfaces is among the central objects of modern geometry: it organizes deformation theory, underlies the perturbative expansion of string theory, and its intersection theory is the subject of a rich body of results. Its dimension,
\[
\dim_{\CC} \M_{g,n} = 3g - 3 + n \qquad (2g-2+n>0),
\]
is classical. The purpose of this paper is to isolate and prove, from first principles, the \emph{exact integer content} of this dimension count, stripped of the analytic machinery needed to construct $\M_{g,n}$ as a space.

We frame the development through a deliberately playful metaphor---the \emph{cake}---that nonetheless tracks the mathematics precisely. A cake has a \emph{base} (a closed orientable surface), \emph{frosting} (a rank-one locally free sheaf on the boundary), and \emph{cherries} (marked points), and its number of handles is counted by its cherries. This metaphor is faithful: ``isomorphism of flavour'' is isomorphism of pointed surfaces, and the classifying space of cakes is $\M_{g,n}$.

Our contributions are: (1) a derivation of the core dimension $3g-3$ by two independent Riemann--Roch computations, proved equal by Serre duality; (2) a precise account of the low-genus repair phenomenon and its equivalence with the stability inequality; (3) a rigid linear triangle connecting Euler characteristic, first Betti number, canonical degree, and moduli dimension; (4) an inductive certification of the closed form via a per-handle recurrence; and (5) the injectivity half of the Fundamental Theorem.

\section{Definitions}

Throughout, $g$ denotes the genus of the base surface and $n$ the number of cherries. We work with integer-valued invariants; the sign structure of the negative low-genus values is essential and would be destroyed by working over the natural numbers.

\begin{definition}[Base topology]
For a closed orientable surface of genus $g$: the \emph{Euler characteristic} is $\chi(g) = 2-2g$, and the \emph{first Betti number} is $b_1(g) = 2g$.
\end{definition}

\begin{definition}[Sheaf degrees]
On a genus-$g$ surface, the \emph{canonical degree} is $\deg K(g) = 2g-2$ and the \emph{tangent degree} is $\deg T(g) = 2-2g$ (so $T_C = K_C^{-1}$).
\end{definition}

\begin{definition}[Riemann--Roch Euler characteristic]
For a line bundle of degree $d$ on a genus-$g$ surface, $\chi(d,g) = h^0 - h^1 = d + 1 - g$.
\end{definition}

\begin{definition}[Moduli and Teichm\"uller dimensions]
The \emph{moduli dimension} of unmarked cakes is $M(g) = 3g-3$; the \emph{marked moduli dimension} is $M(g,n) = 3g-3+n$; the \emph{Teichm\"uller dimension} (real) is $T(g) = 6g-6$; and the \emph{holomorphic-differential dimension} is $H(g) = \chi(\deg K(g), g) + 1$.
\end{definition}

\begin{definition}[Stability]
A cake of genus $g$ with $n$ cherries is \emph{stable} iff $2g-2+n>0$.
\end{definition}

\section{The topology of the base}

\begin{proposition}[Euler via Betti]
$\chi(g) = 1 - b_1(g) + 1$.
\end{proposition}
\begin{proof}
A closed orientable surface has $b_0 = b_2 = 1$ and $b_1 = 2g$, so $\chi = b_0 - b_1 + b_2 = 2 - 2g$.
\end{proof}

\begin{proposition}[Canonical is negative Euler]
$\deg K(g) = -\chi(g)$, and $\deg T(g) = -\deg K(g)$.
\end{proposition}

\begin{proposition}[Holomorphic differentials recover the genus]
$H(g) = g$.
\end{proposition}
\begin{proof}
By Riemann--Roch $\chi(\deg K, g) = (2g-2) + 1 - g = g-1$, hence $H(g) = g$. This recovers $h^0(K_C) = g$.
\end{proof}

\section{The moduli dimension, computed two ways}

\begin{theorem}[Deformation computation]
For a genus-$g$ base, $M(g) = -\chi(\deg T(g), g)$; i.e. the moduli dimension equals $h^1(C, T_C)$, using $h^0(C,T_C)=0$ for $g\ge 2$.
\end{theorem}
\begin{proof}
$-\chi(\deg T, g) = -\big((2-2g)+1-g\big) = -(3-3g) = 3g-3 = M(g)$.
\end{proof}

\begin{theorem}[Quadratic-differential computation]
For a genus-$g$ base, $M(g) = \chi(2\deg K(g), g)$; i.e. the moduli dimension equals $h^0(C, 2K_C)$, the cotangent space to $\M_g$, using $h^1(C,2K_C)=0$ for $g\ge 2$.
\end{theorem}
\begin{proof}
$\chi(2\deg K, g) = 2(2g-2) + 1 - g = (4g-4)+1-g = 3g-3 = M(g)$.
\end{proof}

\begin{theorem}[Serre duality]
$-\chi(\deg T(g), g) = \chi(2\deg K(g), g)$; both equal $3g-3$. The tangent space $H^1(C,T_C)$ and cotangent space $H^0(C,2K_C)$ to moduli are Serre-dual, of common dimension $3g-3$.
\end{theorem}

\begin{proposition}
For $g\ge 2$, $M(g) > 0$, and $M(g+1) = M(g) + 3$: each added handle increases the moduli dimension by exactly three.
\end{proposition}

\section{Cherries repair the exceptional flavours}

The unmarked formula $3g-3$ returns $-3$ at $g=0$ and $0$ at $g=1$. The marked formula corrects this.

\begin{theorem}
$M(0,n) = n-3$ and $M(1,n) = n$.
\end{theorem}
\begin{proof}
Direct substitution. Three cherries fix the $\mathrm{PGL}_2$ automorphism freedom of the projective line; one cherry fixes the origin of an elliptic base.
\end{proof}

\begin{proposition}
$M(g,0) = M(g)$ and $M(g,n+1) = M(g,n)+1$: each cherry contributes exactly one modulus.
\end{proposition}

\begin{theorem}[Stability]
If $g\ge 2$ and $n\ge 0$ then $2g-2+n>0$. Conversely, if $g\ge 0$ and $2g-2+n>0$ then $M(g,n)\ge 0$.
\end{theorem}

Two a priori different notions---\emph{the surface has finitely many automorphisms} and \emph{the naive modulus count is non-negative}---are cut out by the same linear inequality. The exceptional locus is the finite set $\{(0,0),(0,1),(0,2),(1,0)\}$.

\section{The Euler--Betti--moduli triangle}

\begin{theorem}
$T(g) = 2M(g) = 3\deg K(g)$ and $2M(g) = 3b_1(g) - 6$.
\end{theorem}

Combining these,
\[
2\dim\M_g \;=\; -3\chi \;=\; 3b_1 - 6 \;=\; 3\deg K,
\]
a single rigid relation. Any one topological invariant of the base determines the moduli dimension with no analytic input.

\section{Inductive certification and enumeration}

\begin{definition}
Define $R:\NN\to\ZZ$ by $R(0) = -3$ and $R(k+1) = R(k)+3$.
\end{definition}

\begin{theorem}
$R(k) = 3k-3 = M(k)$ for all $k\in\NN$.
\end{theorem}
\begin{proof}
Induction on $k$: base $R(0) = -3$; step $R(k+1) = (3k-3)+3 = 3(k+1)-3$.
\end{proof}

\begin{theorem}[Enumeration for $g\le 5$]
The moduli dimensions for genus $2,3,4,5$ are $3,6,9,12$, each equal to $3g-3$, forming an arithmetic progression with common difference equal to the per-handle step.
\end{theorem}

\section{The Fundamental Theorem: invariants recover the flavour}

\begin{proposition}
If $g=g'$ and $n=n'$ then $M(g,n) = M(g',n')$.
\end{proposition}

\begin{theorem}
The map $g\mapsto M(g)$ is injective and strictly increasing; at fixed $n$, $g\mapsto M(g,n)$ is injective; at fixed $g$, $n\mapsto M(g,n)$ is injective. Hence within a fixed value of one discrete invariant, the moduli dimension recovers the other.
\end{theorem}

This is the honest arithmetic shadow of the statement that a cake is determined up to flavour by its discrete invariants and continuous moduli.

\section{Discussion and future directions}

The reduction of the dimension theorem to elementary integer identities makes the sign structure of the low-genus locus explicit, exhibits stability as the sharp threshold governing both automorphism-finiteness and dimensional validity, and exposes the moduli dimension as a rigid linear image of base topology. The per-handle and per-cherry increments ($+3$ and $+1$) decompose the formula into atomic geometric moves. Three conjectural extensions organize future work: (1) a universal dimension polynomial $\sum_v(3g_v-3+n_v) = 3g-3+n-e$ for every boundary stratum indexed by a stable dual graph; (2) stability as the sharp threshold, with failure locus $\{(0,0),(0,1),(0,2),(1,0)\}$; and (3) the rigid triangle $2\dim\M_g = -3\chi = 3b_1-6$ determining the moduli dimension from any single topological invariant.

\section*{Conclusion}

The number $3g-3+n$ is the common shadow of deformation theory, quadratic differentials, Euler/Betti topology, and the stability inequality. We have proved its arithmetic backbone from two independent Riemann--Roch computations glued by duality, shown that cherries repair the exceptional low-genus flavours exactly at the stability threshold, and chained the moduli dimension to base topology by a rigid linear triangle. Cakes are the moduli of surfaces.

