"""Two Riemann-Roch computations of 3g - 3 and their agreement by Serre duality.

The core moduli dimension of an unmarked genus-g surface is computed twice:
  * via first-order deformations:      -chi(T_C) = -(deg T + 1 - g)
  * via quadratic differentials:        chi(2K_C) = 2*deg K + 1 - g
Both equal 3g - 3; their equality is the Serre-duality identity.
"""
from __future__ import annotations


def rr_chi(d: int, g: int) -> int:
    """Riemann-Roch Euler characteristic of a degree-d line bundle: d + 1 - g."""
    return d + 1 - g


def canonical_deg(g: int) -> int:
    return 2 * g - 2


def tangent_deg(g: int) -> int:
    return 2 - 2 * g


def dim_via_deformations(g: int) -> int:
    return -rr_chi(tangent_deg(g), g)


def dim_via_quadratic(g: int) -> int:
    return rr_chi(2 * canonical_deg(g), g)


def report(max_g: int = 8) -> None:
    print(f"{'g':>3} {'-chi(T_C)':>12} {'chi(2K_C)':>12} {'3g-3':>8}")
    for g in range(2, max_g + 1):
        a, b, c = dim_via_deformations(g), dim_via_quadratic(g), 3 * g - 3
        assert a == b == c
        print(f"{g:>3} {a:>12} {b:>12} {c:>8}")
    print("All three agree: Serre duality confirmed numerically.")


if __name__ == "__main__":
    report()

"""Stability threshold and the low-genus repair by cherries.

A cake of genus g with n cherries is stable iff 2g - 2 + n > 0. This demo
confirms that (a) the exceptional/unstable locus is exactly the finite set
{(0,0),(0,1),(0,2),(1,0)}, and (b) three cherries repair genus 0 while one
cherry repairs genus 1.
"""
from __future__ import annotations


def moduli_dim_marked(g: int, n: int) -> int:
    return 3 * g - 3 + n


def is_stable(g: int, n: int) -> bool:
    return 2 * g - 2 + n > 0


def find_unstable(max_g: int = 6, max_n: int = 10) -> list[tuple[int, int]]:
    return [
        (g, n)
        for g in range(max_g + 1)
        for n in range(max_n + 1)
        if not is_stable(g, n)
    ]


if __name__ == "__main__":
    unstable = find_unstable()
    print("Unstable (exceptional) locus:", unstable)
    assert unstable == [(0, 0), (0, 1), (0, 2), (1, 0)]
    print("Matches the finite failure set {(0,0),(0,1),(0,2),(1,0)}.")
    print()
    print("Genus 0 repaired at n=3:", moduli_dim_marked(0, 3), "= 0 (stable).")
    print("Genus 1 repaired at n=1:", moduli_dim_marked(1, 1), "= 1 (stable).")
